```ts
import {
  attachControl,
  createArcRotateCamera,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });

  attachControl(camera, canvas, scene);
  enableArcRotateKeyboardControls();

  return camera;
}
```

I added `src/orbit-camera.ts`, which creates an ArcRotateCamera 10 units from the origin, attaches the canvas controls, and enables the library arrow-key controls. I chose `alpha = 0` / `beta = Math.PI / 2` as a default and wasn't certain whether your build expects the standalone `enableArcRotateKeyboardControls()` call or the `attachControl` `keyboard: true` option instead.
